import type { ReactNode } from "react";
import { Column, Img, Link, Row } from "react-email";
import { EmailCaption, type EmailFooterPlacement, EmailMutedLink, EmailSection } from "./email";
import {
  EmailAddress,
  EmailFooter,
  type EmailFooterAlign,
  EmailFooterLegal,
  EmailFooterLinks,
  type EmailNavLink,
  type EmailSocialLink,
  EmailSocialLinks,
  EmailUnsubscribe,
} from "./email-footer";
import type { EmailColorScheme } from "./theme";

export type EmailBrand = {
  name: string;
  homeUrl: string;
  logoUrl?: string;
  logoDarkUrl?: string;
  logoWidth?: number;
  logoHeight?: number;
};

export type EmailFooterContent = {
  tagline: string;
  socialLinks: EmailSocialLink[];
  socialIconBaseUrl?: string;
  helpLinks: EmailNavLink[];
  sender: { company: string; addressLines: string[] };
  reason: string;
  legal: string;
  align?: EmailFooterAlign;
  placement?: EmailFooterPlacement;
} & ({ mailing: "transactional" } | { mailing: "marketing"; unsubscribeUrl: string; preferencesUrl?: string });

export function EmailLogo({
  name,
  src,
  width = 120,
  height = 32,
  href,
}: {
  name: string;
  src?: string;
  width?: number;
  height?: number;
  href?: string;
}) {
  const mark = src ? (
    <Img src={src} alt={name} width={width} height={height} className="inline-block" />
  ) : (
    <span className="font-display text-heading-4 font-semibold text-card-foreground">{name}</span>
  );
  return href ? (
    <Link href={href} className="text-card-foreground no-underline">
      {mark}
    </Link>
  ) : (
    mark
  );
}

export function EmailBrowserLink({ href, children = "View in browser" }: { href: string; children?: ReactNode }) {
  return <EmailMutedLink href={href}>{children}</EmailMutedLink>;
}

export type EmailHeaderAlign = "split" | "center";

export function EmailHeader({ children, aside, align = "split" }: { children: ReactNode; aside?: ReactNode; align?: EmailHeaderAlign }) {
  if (align === "center")
    return (
      <EmailSection align="center" className="mb-8">
        {children}
        {aside ? (
          <EmailSection align="center" className="mt-3">
            {aside}
          </EmailSection>
        ) : null}
      </EmailSection>
    );
  return (
    <Row className="mb-8">
      <Column className="align-middle">{children}</Column>
      {aside ? (
        <Column align="right" className="align-middle">
          {aside}
        </Column>
      ) : null}
    </Row>
  );
}

export function EmailBrandHeader({
  brand,
  browserUrl,
  colorScheme = "light",
  align = "split",
}: {
  brand: EmailBrand;
  browserUrl?: string;
  colorScheme?: EmailColorScheme;
  align?: EmailHeaderAlign;
}) {
  const logoUrl = colorScheme === "dark" ? (brand.logoDarkUrl ?? brand.logoUrl) : brand.logoUrl;
  return (
    <EmailHeader align={align} aside={browserUrl ? <EmailBrowserLink href={browserUrl} /> : null}>
      <EmailLogo name={brand.name} src={logoUrl} width={brand.logoWidth} height={brand.logoHeight} href={brand.homeUrl} />
    </EmailHeader>
  );
}

export function EmailBrandFooter({ footer }: { footer: EmailFooterContent }) {
  return (
    <EmailFooter align={footer.align} placement={footer.placement}>
      <EmailSocialLinks links={footer.socialLinks} iconBaseUrl={footer.socialIconBaseUrl} />
      <EmailFooterLinks links={footer.helpLinks} />
      <EmailCaption className="mb-0">{footer.tagline}</EmailCaption>
      <EmailFooterLegal>
        <EmailAddress company={footer.sender.company} lines={footer.sender.addressLines} />
        <EmailCaption className="mb-2">{footer.reason}</EmailCaption>
        {footer.mailing === "marketing" ? (
          <EmailUnsubscribe unsubscribeUrl={footer.unsubscribeUrl} preferencesUrl={footer.preferencesUrl} />
        ) : null}
        <EmailCaption className="mb-0">{footer.legal}</EmailCaption>
      </EmailFooterLegal>
    </EmailFooter>
  );
}

import type { CSSProperties } from "react";
import {
  CodeBlock,
  CodeInline,
  type CodeInlineProps,
  Markdown,
  type MarkdownProps,
  type PrismLanguage,
  type Theme as PrismTheme,
  Section,
} from "react-email";
import { type EmailVariant, surfaceColors } from "./email";
import type { EmailTheme } from "./theme";

export function EmailInlineCode({ className = "", ...props }: CodeInlineProps) {
  return <CodeInline {...props} className={`rounded-control bg-muted px-1 font-mono text-card-foreground ${className}`} />;
}

function prismTheme(theme: EmailTheme): PrismTheme {
  const { code } = theme;
  return {
    base: {
      margin: "0",
      padding: "16px",
      background: theme.colors.muted,
      color: code.foreground,
      borderRadius: theme.radii.panel,
      fontFamily: theme.fonts.mono,
      fontSize: theme.text.caption.fontSize,
      lineHeight: "1.6",
      whiteSpace: "pre-wrap",
      wordBreak: "break-word",
    },
    comment: { color: code.comment },
    prolog: { color: code.comment },
    doctype: { color: code.comment },
    cdata: { color: code.comment },
    punctuation: { color: code.punctuation },
    operator: { color: code.punctuation },
    keyword: { color: code.keyword },
    atrule: { color: code.keyword },
    "attr-value": { color: code.string },
    string: { color: code.string },
    char: { color: code.string },
    inserted: { color: code.string },
    regex: { color: code.string },
    "attr-name": { color: code.parameter },
    property: { color: code.parameter },
    variable: { color: code.parameter },
    function: { color: code.function },
    "class-name": { color: code.function },
    tag: { color: code.function },
    boolean: { color: code.constant },
    number: { color: code.constant },
    constant: { color: code.constant },
    symbol: { color: code.constant },
    deleted: { color: code.constant },
    builtin: { color: code.constant },
  };
}

export function EmailCodeBlock({
  theme,
  code,
  language,
  lineNumbers = false,
  className = "",
}: {
  theme: EmailTheme;
  code: string;
  language: PrismLanguage;
  lineNumbers?: boolean;
  className?: string;
}) {
  return (
    <Section className={`mb-6 ${className}`}>
      <CodeBlock code={code} language={language} lineNumbers={lineNumbers} fontFamily={theme.fonts.mono} theme={prismTheme(theme)} />
    </Section>
  );
}

function markdownStyles(theme: EmailTheme, variant: EmailVariant): NonNullable<MarkdownProps["markdownCustomStyles"]> {
  const colors = surfaceColors(theme, variant);
  const body: CSSProperties = {
    margin: "0 0 16px",
    fontFamily: theme.fonts.body,
    fontSize: theme.text.body.fontSize,
    lineHeight: theme.text.body.lineHeight,
    color: colors["card-foreground"],
  };
  function headingStyle(size: "heading-1" | "heading-2" | "heading-3" | "heading-4"): CSSProperties {
    const style = theme.text[size];
    return {
      margin: "0 0 16px",
      fontFamily: theme.fonts.display,
      fontSize: style.fontSize,
      lineHeight: style.lineHeight,
      fontWeight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      color: colors["card-foreground"],
    };
  }
  const monospace: CSSProperties = {
    fontFamily: theme.fonts.mono,
    fontSize: theme.text.caption.fontSize,
    background: theme.colors.muted,
    color: theme.code.foreground,
    borderRadius: theme.radii.control,
  };
  return {
    p: body,
    li: { ...body, margin: "0 0 4px" },
    ul: { ...body, paddingLeft: "20px" },
    ol: { ...body, paddingLeft: "20px" },
    h1: headingStyle("heading-1"),
    h2: headingStyle("heading-2"),
    h3: headingStyle("heading-3"),
    h4: headingStyle("heading-4"),
    h5: headingStyle("heading-4"),
    h6: headingStyle("heading-4"),
    bold: { fontWeight: 600 },
    italic: { fontStyle: "italic" },
    link: { color: colors["primary-text"], textDecoration: "underline" },
    codeInline: { ...monospace, padding: "2px 4px" },
    codeBlock: { ...monospace, display: "block", padding: "16px", borderRadius: theme.radii.panel, whiteSpace: "pre-wrap" },
    blockQuote: {
      ...body,
      borderLeft: `3px solid ${theme.colors.border}`,
      paddingLeft: "16px",
      color: colors["muted-foreground"],
    },
    hr: { border: "none", borderTop: `1px solid ${theme.colors.border}`, margin: "24px 0" },
    image: { maxWidth: "100%", borderRadius: theme.radii.scene },
    table: { width: "100%", borderCollapse: "collapse", marginBottom: "16px" },
    th: { ...body, margin: "0", textAlign: "left", padding: "8px 0", borderBottom: `1px solid ${theme.colors.border}` },
    td: { ...body, margin: "0", padding: "8px 0", borderBottom: `1px solid ${theme.colors.border}` },
  };
}

export function EmailMarkdown({ theme, variant = "contained", children }: { theme: EmailTheme; variant?: EmailVariant; children: string }) {
  return <Markdown markdownCustomStyles={markdownStyles(theme, variant)}>{children}</Markdown>;
}

import { Fragment, type ReactNode } from "react";
import { Img, Section } from "react-email";
import { EmailCaption, EmailDivider, type EmailFooterPlacement, EmailMutedLink } from "./email";

export type EmailNavLink = { label: string; href: string };

export const emailSocialPlatformNames = {
  x: "X",
  bluesky: "Bluesky",
  threads: "Threads",
  instagram: "Instagram",
  facebook: "Facebook",
  linkedin: "LinkedIn",
  youtube: "YouTube",
  tiktok: "TikTok",
  github: "GitHub",
  discord: "Discord",
  slack: "Slack",
  mastodon: "Mastodon",
} as const;

export type EmailSocialPlatform = keyof typeof emailSocialPlatformNames;
export type EmailSocialLink = { href: string; iconAlt?: string } & (
  | { platform: EmailSocialPlatform; label?: string; iconUrl?: string }
  | { platform?: undefined; label: string; iconUrl?: string }
);
export type EmailFooterAlign = "start" | "center";

function separatedLinks(links: EmailNavLink[]) {
  return links.map((link, index) => (
    <Fragment key={link.href}>
      {index > 0 ? " · " : null}
      <EmailMutedLink href={link.href}>{link.label}</EmailMutedLink>
    </Fragment>
  ));
}

export function EmailFooter({
  children,
  align = "start",
  placement = "inside",
}: {
  children: ReactNode;
  align?: EmailFooterAlign;
  placement?: EmailFooterPlacement;
}) {
  return (
    <>
      {placement === "inside" ? <EmailDivider /> : null}
      <Section className={`${placement === "inside" ? "" : "pt-6"} ${align === "center" ? "text-center" : "text-left"}`}>
        {children}
      </Section>
    </>
  );
}

export function EmailFooterLegal({ children, className = "" }: { children: ReactNode; className?: string }) {
  return <Section className={`mt-6 ${className}`}>{children}</Section>;
}

function resolveSocialLink(link: EmailSocialLink, iconBaseUrl?: string) {
  const label = link.platform ? (link.label ?? emailSocialPlatformNames[link.platform]) : link.label;
  const base = iconBaseUrl?.replace(/\/$/, "");
  const iconUrl = link.iconUrl ?? (link.platform && base ? `${base}/${link.platform}.png` : undefined);
  return { label, iconUrl, alt: link.iconAlt ?? label };
}

export function EmailSocialLinks({
  links,
  iconBaseUrl,
  iconSize = 24,
}: {
  links: EmailSocialLink[];
  iconBaseUrl?: string;
  iconSize?: number;
}) {
  if (links.length === 0) return null;
  return (
    <Section className="mb-4">
      {links.map((link, index) => {
        const { label, iconUrl, alt } = resolveSocialLink(link, iconBaseUrl);
        const spacing = index < links.length - 1 ? "mr-3" : "";
        return (
          <Fragment key={link.href}>
            {index > 0 ? " " : null}
            <EmailMutedLink href={link.href} className={`${iconUrl ? "no-underline" : "underline"} ${spacing}`}>
              {iconUrl ? <Img src={iconUrl} alt={alt} width={iconSize} height={iconSize} className="inline-block align-middle" /> : label}
            </EmailMutedLink>
          </Fragment>
        );
      })}
    </Section>
  );
}

export function EmailFooterLinks({ links }: { links: EmailNavLink[] }) {
  if (links.length === 0) return null;
  return <EmailCaption className="mb-2">{separatedLinks(links)}</EmailCaption>;
}

export function EmailAddress({ company, lines }: { company: string; lines: string[] }) {
  return (
    <EmailCaption className="mb-2">
      <strong className="font-semibold">{company}</strong>
      {lines.map((line) => (
        <Fragment key={line}>
          <br />
          {line}
        </Fragment>
      ))}
    </EmailCaption>
  );
}

export function EmailUnsubscribe({
  unsubscribeUrl,
  preferencesUrl,
  unsubscribeLabel = "Unsubscribe",
  preferencesLabel = "Manage preferences",
}: {
  unsubscribeUrl: string;
  preferencesUrl?: string;
  unsubscribeLabel?: string;
  preferencesLabel?: string;
}) {
  const unsubscribe = { label: unsubscribeLabel, href: unsubscribeUrl };
  const links = preferencesUrl ? [unsubscribe, { label: preferencesLabel, href: preferencesUrl }] : [unsubscribe];
  return <EmailCaption className="mb-2">{separatedLinks(links)}</EmailCaption>;
}

import type { ReactNode } from "react";
import {
  Body,
  Button,
  type ButtonProps,
  Column,
  Container,
  Head,
  Heading,
  type HeadingProps,
  Hr,
  type HrProps,
  Html,
  Link,
  type LinkProps,
  Preview,
  pixelBasedPreset,
  Row,
  Section,
  type SectionProps,
  Tailwind,
  type TailwindConfig,
  Text,
  type TextProps,
} from "react-email";
import type { EmailTheme } from "./theme";

export type EmailVariant = "contained" | "plain";
export type EmailFooterPlacement = "inside" | "outside";

export function surfaceColors(theme: EmailTheme, variant: EmailVariant) {
  if (variant === "contained") return theme.colors;
  return { ...theme.colors, card: theme.colors.background, "card-foreground": theme.colors.foreground };
}

function tailwindTheme(theme: EmailTheme, variant: EmailVariant): TailwindConfig {
  return {
    presets: [pixelBasedPreset],
    theme: {
      extend: {
        colors: surfaceColors(theme, variant),
        borderRadius: theme.radii,
        minHeight: { control: theme.button.height },
        padding: { "control-x": theme.button.paddingInline, "control-y": theme.button.paddingBlock },
        fontFamily: { body: theme.fonts.body, display: theme.fonts.display, mono: theme.fonts.mono },
        fontSize: {
          ...Object.fromEntries(Object.entries(theme.text).map(([name, { fontSize, ...options }]) => [name, [fontSize, options]])),
          control: [theme.button.fontSize, { lineHeight: theme.button.lineHeight }],
        },
      },
    },
  };
}

export function EmailLayout({
  theme,
  preview,
  children,
  footer,
  footerPlacement = "inside",
  head,
  lang = "en",
  dir = "ltr",
  variant = "contained",
}: {
  theme: EmailTheme;
  preview: string;
  children: ReactNode;
  footer?: ReactNode;
  footerPlacement?: EmailFooterPlacement;
  head?: ReactNode;
  lang?: string;
  dir?: "ltr" | "rtl";
  variant?: EmailVariant;
}) {
  const contained = variant === "contained";
  const outside = contained && footerPlacement === "outside";
  const backdrop = theme.colorScheme === "light" ? "bg-muted" : "bg-background";
  return (
    <Html lang={lang} dir={dir}>
      <Tailwind config={tailwindTheme(theme, variant)}>
        <Head>
          <meta name="color-scheme" content={theme.colorScheme} />
          <meta name="supported-color-schemes" content={theme.colorScheme} />
          {head}
        </Head>
        <Body className={`m-0 font-body text-body text-foreground ${contained ? `${backdrop} px-4 py-8` : "bg-background p-0"}`}>
          <Preview>{preview}</Preview>
          <Container
            className={`mx-auto w-full max-w-[600px] bg-card text-card-foreground ${contained ? "rounded-panel border border-border border-solid p-6" : "px-6 py-8"}`}
          >
            {children}
            {outside ? null : footer}
          </Container>
          {outside ? <Container className="mx-auto w-full max-w-[600px] px-6">{footer}</Container> : null}
        </Body>
      </Tailwind>
    </Html>
  );
}

export type EmailAlign = "left" | "center" | "right";

const alignClasses = { left: "text-left", center: "text-center", right: "text-right" };

function alignClass(align?: EmailAlign) {
  return align ? alignClasses[align] : "";
}

const headingSizeClasses = {
  display: "text-display",
  "heading-1": "text-heading-1",
  "heading-2": "text-heading-2",
  "heading-3": "text-heading-3",
  "heading-4": "text-heading-4",
};

type EmailHeadingSize = keyof typeof headingSizeClasses;

const headingSizeForTag = { h1: "heading-1", h2: "heading-2", h3: "heading-3", h4: "heading-4" } as const;

export function EmailHeading({
  as = "h1",
  size,
  align,
  className = "",
  ...props
}: Omit<HeadingProps, "as"> & { as?: keyof typeof headingSizeForTag; size?: EmailHeadingSize; align?: EmailAlign }) {
  const sizeClass = headingSizeClasses[size ?? headingSizeForTag[as]];
  return (
    <Heading {...props} as={as} className={`mb-4 mt-0 font-display text-card-foreground ${sizeClass} ${alignClass(align)} ${className}`} />
  );
}

export function EmailSection({ align, className = "", ...props }: SectionProps & { align?: EmailAlign }) {
  return <Section {...props} className={`${alignClass(align)} ${className}`} />;
}

export function EmailText({
  tone = "default",
  align,
  className = "",
  style,
  ...props
}: TextProps & { tone?: "default" | "muted"; align?: EmailAlign }) {
  const textColor = tone === "muted" ? "text-muted-foreground" : "text-card-foreground";
  return (
    <Text
      {...props}
      style={{ overflowWrap: "break-word", ...style }}
      className={`mb-4 mt-0 font-body text-body ${textColor} ${alignClass(align)} ${className}`}
    />
  );
}

export function EmailButton({ width = "auto", className = "", ...props }: ButtonProps & { width?: "auto" | "full" }) {
  const widthClass = width === "full" ? "block w-full" : "inline-block";
  return (
    <Button
      {...props}
      className={`box-border min-h-control rounded-control bg-primary px-control-x py-control-y text-center font-body text-control font-medium text-primary-foreground no-underline ${widthClass} ${className}`}
    />
  );
}

export function EmailLink({ className = "", ...props }: LinkProps) {
  return <Link {...props} className={`font-body text-primary-text underline ${className}`} />;
}

export function EmailCaption({ className = "", ...props }: TextProps & { align?: EmailAlign }) {
  return <EmailText tone="muted" {...props} className={`text-caption ${className}`} />;
}

export function EmailMutedLink({ className = "", ...props }: LinkProps) {
  return <EmailLink {...props} className={`text-caption text-muted-foreground ${className}`} />;
}

export function EmailDivider({ className = "", ...props }: HrProps) {
  return <Hr {...props} className={`my-6 border-0 border-t border-solid border-t-border ${className}`} />;
}

export function EmailPanel({ className = "", ...props }: SectionProps) {
  return <Section {...props} className={`my-6 rounded-panel bg-muted p-5 ${className}`} />;
}

export function EmailOneTimeCode({ children, className = "" }: { children: ReactNode; className?: string }) {
  return (
    <EmailPanel className={`text-center ${className}`}>
      <EmailText className="mb-0 text-center font-mono text-heading-2 font-semibold tracking-[0.25em]">{children}</EmailText>
    </EmailPanel>
  );
}

export function EmailBulletList({ items, className = "" }: { items: ReactNode[]; className?: string }) {
  if (items.length === 0) return null;
  return (
    <ul className={`mb-4 mt-0 list-disc pl-5 font-body text-body text-card-foreground ${className}`}>
      {items.map((item, index) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: list entries are positional content with no stable identity.
        <li key={index} className="mb-1 font-body text-body text-card-foreground">
          {item}
        </li>
      ))}
    </ul>
  );
}

export function EmailColumns({
  children,
  widths,
  gap = 20,
  verticalAlign = "top",
  className = "",
}: {
  children: ReactNode[];
  widths?: string[];
  gap?: number;
  verticalAlign?: "top" | "middle" | "bottom";
  className?: string;
}) {
  if (children.length === 0) return null;
  const evenWidth = `${(100 / children.length).toFixed(4)}%`;
  return (
    <Row className={`mb-6 table-fixed ${className}`}>
      {children.map((child, index) => (
        <Column
          // biome-ignore lint/suspicious/noArrayIndexKey: columns are positional slots with no stable identity.
          key={index}
          width={widths?.[index] ?? evenWidth}
          className={`max-[480px]:block max-[480px]:w-full max-[480px]:pl-0 ${index === 0 ? "" : `max-[480px]:pt-[${gap}px]`}`}
          style={{ verticalAlign, paddingLeft: index === 0 ? 0 : gap }}
        >
          {child}
        </Column>
      ))}
    </Row>
  );
}

export function EmailDetailRow({ label, value, emphasis = false }: { label: ReactNode; value: ReactNode; emphasis?: boolean }) {
  const valueWeight = emphasis ? "font-semibold" : "";
  return (
    <Row className="table-fixed">
      <Column className="align-top">
        <EmailText className="mb-2">{label}</EmailText>
      </Column>
      <Column align="right" className="align-top">
        <EmailText className={`mb-2 ${valueWeight}`}>{value}</EmailText>
      </Column>
    </Row>
  );
}

function parseLengthQuantity(value: string, rootFontSize: number) {
  const match = /^(-?\d*\.?\d+)(px|rem)?$/.exec(value.trim());
  if (!match) return null;
  return { amount: Number(match[1]) * (match[2] === "rem" ? rootFontSize : 1), unit: match[2] ? "px" : "" };
}

function calculateLengthExpression(expression: string, rootFontSize: number) {
  const match = /^\s*(-?\d*\.?\d+(?:px|rem)?)\s*([+*/-])\s*(-?\d*\.?\d+(?:px|rem)?)\s*$/.exec(expression);
  if (!match) return null;
  const left = parseLengthQuantity(match[1], rootFontSize);
  const right = parseLengthQuantity(match[3], rootFontSize);
  if (!left || !right) return null;
  const operator = match[2];
  if ((operator === "+" || operator === "-") && left.unit === right.unit) {
    return `${left.amount + (operator === "+" ? right.amount : -right.amount)}${left.unit}`;
  }
  if (operator === "*" && !(left.unit && right.unit)) return `${left.amount * right.amount}${left.unit || right.unit}`;
  const dividesByScalar = operator === "/" && !right.unit && right.amount !== 0;
  if (dividesByScalar) return `${left.amount / right.amount}${left.unit}`;
  return null;
}

export function emailLengthPixels(name: string, value: string, rootFontSize: number, allowZero = false): number {
  let resolved = value;
  for (let depth = 0; depth < 16 && resolved.includes("calc("); depth++) {
    const simplified = resolved.replace(
      /calc\(([^()]*)\)/g,
      (original, expression: string) => calculateLengthExpression(expression, rootFontSize) ?? original,
    );
    if (simplified === resolved) break;
    resolved = simplified;
  }
  const result = parseLengthQuantity(resolved, rootFontSize);
  const isLength = result && (result.unit === "px" || result.amount === 0);
  const isValidLength = isLength && Number.isFinite(result.amount) && (allowZero ? result.amount >= 0 : result.amount > 0);
  if (!isValidLength) {
    throw new Error(`Email theme: ${name} must resolve to a ${allowZero ? "non-negative" : "positive"} px/rem length, received ${value}.`);
  }
  return result.amount;
}

import type { ReactNode } from "react";
import { Column, Img, type PrismLanguage, Row } from "react-email";
import {
  EmailBulletList,
  EmailButton,
  EmailCaption,
  EmailColumns,
  EmailDetailRow,
  EmailDivider,
  EmailHeading,
  EmailLayout,
  EmailLink,
  EmailOneTimeCode,
  EmailPanel,
  EmailSection,
  EmailText,
  type EmailVariant,
} from "./email";
import { type EmailBrand, EmailBrandFooter, EmailBrandHeader, type EmailFooterContent } from "./email-brand";
import { EmailCodeBlock, EmailInlineCode, EmailMarkdown } from "./email-code";
import type { EmailTheme } from "./theme";

type EmailMessageProps = { theme: EmailTheme; brand: EmailBrand; footer: EmailFooterContent; variant?: EmailVariant; head?: ReactNode };
type EmailBrandProps = EmailMessageProps & { browserUrl?: string };

export type EmailHighlight = { title: string; description: string };

export function InvitationEmail({
  theme,
